fn clear_and_fill(v: &mut Vec[Int], n: Int) -> Unit {
  v.clear();
  var i = 1;
  while i <= n {
    v.push(i);
    i = i + 1;
  }
}

fn reverse_in_place(v: &mut Vec[Int]) -> Unit {
  var left = 0;
  var right = v.len() - 1;
  while left < right {
    let temp = v[left];
    v[left] = v[right];
    v[right] = temp;
    left = left + 1;
    right = right - 1;
  }
}

fn main() -> Int {
  var v = Vec[Int]();
  v.push(1);
  v.push(2);
  v.push(3);
  reverse_in_place(&mut v);
  return v[0];
}
